// SEED-1-DUMMY — generate a seed table (SEED-1 §4.4). PURE and SEEDED: the same
// options produce the same table byte-for-byte, so a regenerated table is the
// same table and its keys resume rather than duplicate.
// NEVER import this from src/**.
//
// SEED-DEPTH2 (test branch `test/seed-depth2-load`, not merged): the structure
// is now posts / depth-1 replies / depth-2 replies per market, with even due
// spacing and `[DUMMY]` bodies. Tables generated by the pre-depth-2 generator
// are still VALID tables (depth <= 1) but the same seed no longer reproduces
// them, so resume such a run with its existing table.json, never a regenerated one.

import {
	AUTHOR_SPEND_CAP,
	rowKey,
	type SeedKind,
	type SeedRow,
	type SeedSide,
	type SeedTable,
	validateTable,
} from "./table";

export interface GenerateOptions {
	readonly runId: string;
	readonly markets: readonly string[];
	/** Account budget. Every label is used before any is reused. */
	readonly users: number;
	/** Depth-0 rows per market. */
	readonly postsPerMarket: number;
	/**
	 * SEED-DEPTH2: depth-1 rows per market (a Support/Counter on a post). Parents
	 * are dealt round-robin over the market's shuffled posts, so every post gets
	 * a reply before any gets a second. Replaced the old `coverage` knob.
	 */
	readonly repliesPerMarket: number;
	/**
	 * SEED-DEPTH2: depth-2 rows per market (a Support/Counter on a depth-1
	 * reply), dealt round-robin over the market's shuffled depth-1 rows.
	 */
	readonly depth2PerMarket: number;
	/** Share of posts on YES (SEED-1 §4.4 step 1). */
	readonly yesRatio: number;
	/** Share of posts that carry an image (SEED-1 D10). 0 = no images. */
	readonly imageRatio: number;
	readonly imageExt: string;
	/** 0 = every row due immediately; otherwise rows are spread over this window. */
	readonly windowMs: number;
	/**
	 * SEED-DEPTH2: how due offsets fill the window. `even` puts row i at
	 * floor(i * windowMs / rows) — a constant gap, so a load log reads cleanly —
	 * and draws NOTHING from the RNG, so the same seed gives byte-identical rows
	 * (keys, authors, stakes, fingerprints) at any window; only `dueOffsetMs`
	 * moves. `random` is the original sorted-uniform draw.
	 */
	readonly spacing: "even" | "random";
	readonly seed: number;
}

/** SEED-1 §4.4 step 2 — most participants bet the floor; a few bet more. */
const POST_STAKE_LADDER = [10, 10, 15, 20, 25, 40] as const;
/** SEED-1 §4.4 step 3 — reply stakes drawn by SIDE, not by role. */
const REPLY_STAKE_BAND: Record<SeedSide, readonly [number, number]> = {
	NO: [90, 130],
	YES: [50, 80],
};

/** mulberry32 — small, seedable, deterministic. Not for anything secret. */
function rng(seed: number): () => number {
	let a = seed >>> 0;
	return () => {
		a = (a + 0x6d2b79f5) >>> 0;
		let t = a;
		t = Math.imul(t ^ (t >>> 15), t | 1);
		t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
	};
}

function shuffle<T>(items: T[], rand: () => number): T[] {
	for (let i = items.length - 1; i > 0; i--) {
		const j = Math.floor(rand() * (i + 1));
		[items[i], items[j]] = [items[j] as T, items[i] as T];
	}
	return items;
}

function intIn(rand: () => number, lo: number, hi: number): number {
	return lo + Math.floor(rand() * (hi - lo + 1));
}

/** SEED-DEPTH2: content does not matter for this run; the [DUMMY] marker does. */
function body(kind: SeedKind): string {
	if (kind === "post") return "[DUMMY] Post";
	return kind === "support" ? "[DUMMY] Support" : "[DUMMY] Counter";
}

/** One row-to-be, before it has an author, a seq or a key. */
interface Slot {
	readonly market: string;
	readonly marketIdx: number;
	readonly kind: SeedKind;
	readonly postNo: number;
	readonly depth: number;
	readonly side: SeedSide;
	readonly parent: Slot | null;
	readonly image: boolean;
	/** Position within its market's timeline; normalised to 0..1 as `t`. */
	readonly pos: number;
	t: number;
}

/**
 * Timeline shape (SEED-DEPTH2). Posts are born POST_SPACING apart and a reply
 * lands 5..5+REPLY_GAP after its parent, so each thread finishes well before the
 * market's last post: depths 0/1/2 are mixed through the WHOLE run instead of
 * all posts first and all replies last — which is what a load log wants, and
 * what lets a short `--limit` rehearsal reach depth 2.
 */
const POST_SPACING = 30;
const REPLY_GAP = 40;

function opposite(side: SeedSide): SeedSide {
	return side === "YES" ? "NO" : "YES";
}

/** `count` stances, half support and half counter, in a seeded order. */
function stances(count: number, rand: () => number): SeedKind[] {
	return shuffle(
		Array.from({ length: count }, (_, i) =>
			i % 2 === 0 ? ("support" as const) : ("counter" as const),
		),
		rand,
	);
}

export function generateTable(opts: GenerateOptions): SeedTable {
	const rand = rng(opts.seed);

	// ── Per-market trees, then one global interleave (§4.4 step 6) ─────────
	const slots: Slot[] = [];

	opts.markets.forEach((market, marketIdx) => {
		const n = opts.postsPerMarket;
		if (n < 1) throw new Error("postsPerMarket must be at least 1");
		if (opts.depth2PerMarket > 0 && opts.repliesPerMarket < 1)
			throw new Error("depth-2 rows need at least one depth-1 row per market");
		const indices = () => Array.from({ length: n }, (_, i) => i + 1);
		const yes = new Set(
			shuffle(indices(), rand).slice(0, Math.round(n * opts.yesRatio)),
		);
		const withImage = new Set(
			shuffle(indices(), rand).slice(0, Math.round(n * opts.imageRatio)),
		);

		const local: Slot[] = [];
		const posts: Slot[] = [];
		for (let postNo = 1; postNo <= n; postNo++) {
			const post: Slot = {
				market,
				marketIdx,
				kind: "post",
				postNo,
				depth: 0,
				side: yes.has(postNo) ? "YES" : "NO",
				parent: null,
				image: withImage.has(postNo),
				pos: postNo * POST_SPACING + rand() * POST_SPACING,
				t: 0,
			};
			posts.push(post);
			local.push(post);
		}

		// Replies at depth d are dealt round-robin over the shuffled rows at
		// depth d-1; side is relative to that IMMEDIATE parent.
		const replyLayer = (parents: Slot[], count: number): Slot[] => {
			const order = shuffle([...parents], rand);
			const kinds = stances(count, rand);
			return kinds.map((kind, i) => {
				const parent = order[i % order.length] as Slot;
				const reply: Slot = {
					market,
					marketIdx,
					kind,
					postNo: parent.postNo,
					depth: parent.depth + 1,
					side: kind === "support" ? parent.side : opposite(parent.side),
					parent,
					image: false,
					// Strictly after the parent, so the parent always runs first.
					pos: parent.pos + 5 + rand() * REPLY_GAP,
					t: 0,
				};
				local.push(reply);
				return reply;
			});
		};
		const depth1 = replyLayer(posts, opts.repliesPerMarket);
		replyLayer(depth1, opts.depth2PerMarket);

		local.sort((a, b) => a.pos - b.pos);
		const max = local[local.length - 1]?.pos ?? 1;
		for (const s of local) {
			s.t = s.pos / max;
			slots.push(s);
		}
	});
	// Stable sort: ties keep market order, and within a market the local order.
	slots.sort((a, b) => a.t - b.t);

	// ── Due offsets (non-decreasing, so execution order is due order) ──────
	const offsets =
		opts.windowMs <= 0
			? slots.map(() => 0)
			: opts.spacing === "even"
				? slots.map((_, i) => Math.floor((i * opts.windowMs) / slots.length))
				: slots
						.map(() => Math.floor(rand() * opts.windowMs))
						.sort((a, b) => a - b);

	// ── Authors (§4.4 step 5) ──────────────────────────────────────────────
	const width = Math.max(4, String(opts.users).length);
	const unused = shuffle(
		Array.from(
			{ length: opts.users },
			(_, i) => `A${String(i + 1).padStart(width, "0")}`,
		),
		rand,
	);
	const used: string[] = [];
	const spend = new Map<string, number>();
	const held = new Map<string, SeedSide>();
	const authorOf = new Map<Slot, string>();
	const keyOf = new Map<Slot, string>();
	const seqByMarket = new Map<string, number>();
	let lastAuthor: string | null = null;

	const rows: SeedRow[] = slots.map((slot, i) => {
		const { side } = slot;
		const [lo, hi] = REPLY_STAKE_BAND[side];
		const stake =
			slot.kind === "post"
				? POST_STAKE_LADDER[Math.floor(rand() * POST_STAKE_LADDER.length)]
				: intIn(rand, lo, hi);

		const eligible = (a: string) =>
			a !== lastAuthor &&
			(spend.get(a) ?? 0) + stake <= AUTHOR_SPEND_CAP &&
			(held.get(`${a}|${slot.market}`) ?? side) === side &&
			(slot.parent === null || authorOf.get(slot.parent) !== a);

		let author = unused.length > 0 ? (unused.pop() as string) : null;
		if (author !== null) used.push(author);
		for (let tries = 0; author === null && tries < 64; tries++) {
			const pick = used[Math.floor(rand() * used.length)] as string;
			if (eligible(pick)) author = pick;
		}
		author ??= used.find(eligible) ?? null;
		if (author === null) {
			throw new Error(
				`not enough authors: row ${i} (${slot.market} post ${slot.postNo} ${slot.kind} depth ${slot.depth}) has no eligible account — raise --users`,
			);
		}

		spend.set(author, (spend.get(author) ?? 0) + stake);
		held.set(`${author}|${slot.market}`, side);
		lastAuthor = author;

		const seq = (seqByMarket.get(slot.market) ?? 0) + 1;
		seqByMarket.set(slot.market, seq);
		const key = rowKey(opts.runId, slot.marketIdx, seq);
		authorOf.set(slot, author);
		keyOf.set(slot, key);

		return {
			key,
			market: slot.market,
			seq,
			postNo: slot.postNo,
			kind: slot.kind,
			side,
			stake: String(stake),
			author,
			body: body(slot.kind),
			parentKey:
				slot.parent === null ? null : (keyOf.get(slot.parent) as string),
			image: slot.image
				? `${slot.market}_p${String(slot.postNo).padStart(3, "0")}.${opts.imageExt}`
				: null,
			dueOffsetMs: offsets[i] as number,
		};
	});
	const table: SeedTable = {
		runId: opts.runId,
		markets: [...opts.markets],
		rows,
	};
	const errors = validateTable(table);
	if (errors.length > 0) {
		throw new Error(
			`generated table failed validation (${errors.length}):\n  ${errors.slice(0, 20).join("\n  ")}`,
		);
	}
	return table;
}
